const MAX_PAGES = 8;
const pages = [];

for (let i = 1; i <= MAX_PAGES; i++) {
  pages.push({
    json: {
      source_site: "readthetale",
      crawl_type: "catalog",
      page_num: i,
      url: i === 1
        ? "https://www.readthetale.com/popular-bedtime-stories"
        : `https://www.readthetale.com/popular-bedtime-stories/?_page=${i}`
    }
  });
}

return pages;

function simpleHash(str) {
  let hash = 0n;
  for (let i = 0; i < str.length; i++) {
    hash = (hash * 31n + BigInt(str.charCodeAt(i))) & 0xFFFFFFFFFFFFFFFFn;
  }
  return hash.toString(16).padStart(16, '0');
}

const results = [];

for (const inputItem of $input.all()) {
  const item = inputItem.json;
  const html = item.html || '';
  const pageNum = parseInt(item.page_num || 1, 10);
  const statusCode = item.statusCode || item.status || 200;

  if (statusCode !== 200 || !html) {
    results.push({ json: { _skip: true, page_num: pageNum, error_type: 'http_error' } });
    continue;
  }

  const storyRegex = /<h4[^>]*class="[^"]*pt-cv-title[^"]*"[^>]*>\s*<a\s+href="(https:\/\/www\.readthetale\.com\/popular-bedtime-stories\/[^"]+)"[^>]*>([^<]+)<\/a>/g;
  const likesMatches = [...html.matchAll(/❤️(\d+)/g)];

  let match;
  let likeIndex = 0;
  let pageResults = [];

  while ((match = storyRegex.exec(html)) !== null) {
    const url = match[1].trim();
    const title = match[2].trim();
    const likes = likesMatches[likeIndex] ? parseInt(likesMatches[likeIndex][1], 10) : null;
    likeIndex++;

    pageResults.push({
      json: {
        catalog_id: simpleHash(url),
        source_title: title,
        story_url: url,
        comments: null,
        likes,
        popularity_score: likes,
        page_num: pageNum,
        rank: (pageNum - 1) * 10 + pageResults.length + 1,
        source_site: 'readthetale',
        crawl_type: item.crawl_type || 'catalog',
        source_language: 'en',
        source_region: 'global',
        source_type: 'fairy_tale',
        ingested: false,
        discovered_at: new Date().toISOString()
      }
    });
  }

  if (pageResults.length === 0) {
    results.push({ json: { _skip: true, page_num: pageNum, error_type: 'no_matches' } });
  } else {
    results.push(...pageResults);
  }
}

return results;

const all = $input
  .all()
  .map(item => item.json)
  .filter(s => !s._skip && s.catalog_id && s.story_url);

// Deduplicate by catalog_id
const seen = new Set();
const unique = all.filter(s => {
  if (seen.has(s.catalog_id)) return false;
  seen.add(s.catalog_id);
  return true;
});

// Sort by popularity
unique.sort((a, b) => (b.popularity_score || 0) - (a.popularity_score || 0));

// Keep top 100 and rank
return unique.slice(0, 100).map((story, i) => ({
  json: {
    catalog_id: String(story.catalog_id),
    source_title: String(story.source_title),
    story_url: String(story.story_url),
    rank: Number(i + 1),
    page_num: Number(story.page_num),
    catalog_version: Number(1),
    status: "pending",
    likes: story.likes ?? null,
    comments: story.comments ?? null,
    popularity_score: story.popularity_score ?? null,
    source_site: String(story.source_site),
    source_language: String(story.source_language),
    source_region: String(story.source_region),
    source_type: String(story.source_type),
    crawl_type: String(story.crawl_type),
    discovered_at: String(story.discovered_at)
  }
}));
